class Money:
    def __init__(self, cents):
        self.cents = cents

    def __add__(self, o):
        return Money(self.cents + o.cents)

    def __eq__(self, o):
        return isinstance(o, Money) and self.cents == o.cents

    def __repr__(self):
        return f'Money({self.cents})'

    def __str__(self):
        sign = '-' if self.cents < 0 else ''
        amount = abs(self.cents) / 100
        return f'{sign}${amount:,.2f}'

    def split(self, n):
        share, remainder = divmod(self.cents, n)
        parts = []
        for i in range(n):
            extra = 1 if i < remainder else 0
            parts.append(Money(share + extra))
        return parts
